DROP PROCEDURE IF EXISTS `ms_aq20_cache_restore_20261007`;
DELIMITER $$
CREATE PROCEDURE `ms_aq20_cache_restore_20261007`()
BEGIN
    DECLARE `normal_aq20` INT UNSIGNED DEFAULT 0;
    DECLARE `heroic_aq20` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_aq20` INT UNSIGNED DEFAULT 0;
    DECLARE `mythic_bwl` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_11_20` INT UNSIGNED DEFAULT 0;
    DECLARE `dungeon_21_30` INT UNSIGNED DEFAULT 0;
    DECLARE EXIT HANDLER FOR SQLEXCEPTION
    BEGIN
        ROLLBACK;
        RESIGNAL;
    END;
    IF (SELECT COUNT(*) FROM `information_schema`.`TABLES`
        WHERE `TABLE_SCHEMA` = DATABASE() AND `TABLE_NAME` IN ('item_loot_template', 'reference_loot_template')
            AND `ENGINE` = 'InnoDB') <> 2 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: InnoDB loot tables required';
    END IF;
    START TRANSACTION;
    IF (SELECT COUNT(*) FROM `tmp_ms_aq20_candidate`) <> 12714 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: expected 12714 candidate assignments';
    END IF;
    -- One scan: MySQL cannot reopen a temporary table twice in one statement.
    SELECT COUNT(CASE WHEN `Pool` = 9003501 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003502 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003503 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003504 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003505 THEN 1 END),
        COUNT(CASE WHEN `Pool` = 9003506 THEN 1 END)
    INTO `normal_aq20`, `heroic_aq20`, `mythic_aq20`, `mythic_bwl`,
        `dungeon_11_20`, `dungeon_21_30`
    FROM `tmp_ms_aq20_candidate`;
    IF `normal_aq20` <> 144 OR `heroic_aq20` <> 124 OR `mythic_aq20` <> 144
        OR `mythic_bwl` <> 82 OR `dungeon_11_20` <> 6110 OR `dungeon_21_30` <> 6110 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: candidate family count mismatch';
    END IF;
    IF (SELECT COUNT(*) FROM `item_template`
        WHERE `entry` IN (1278070, 1278072, 1278074) AND (`Flags` & 4) <> 0 AND `ScriptName` = '') <> 3 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: missing scriptless HAS_LOOT containers';
    END IF;
    IF EXISTS (
        SELECT 1 FROM `tmp_ms_aq20_candidate` AS `c`
        LEFT JOIN `item_template` AS `i` ON `i`.`entry` = `c`.`Item`
        WHERE `i`.`entry` IS NULL OR BINARY `i`.`name` <> BINARY `c`.`Name`
            OR `i`.`class` <> `c`.`Class` OR `i`.`subclass` <> `c`.`Subclass`
            OR `i`.`InventoryType` <> `c`.`InventoryType` OR `i`.`Quality` <> `c`.`Quality`
            OR `i`.`RequiredLevel` <> `c`.`RequiredLevel` OR `i`.`displayid` <> `c`.`DisplayId`
            OR `i`.`ItemLevel` <> `c`.`ItemLevel`
            OR BINARY `i`.`description` <> BINARY `c`.`Description`
            OR `i`.`RequiredLevel` > 60 OR `i`.`class` NOT IN (2, 4) OR `i`.`InventoryType` = 0
    ) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: candidate metadata mismatch';
    END IF;
    IF EXISTS (SELECT 1 FROM `reference_loot_template`
        WHERE `Entry` IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506)
            AND `Comment` <> 'MS Classic AQ20 cache family pool')
        OR EXISTS (SELECT 1 FROM `reference_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `item_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506)
                AND `Entry` NOT IN (1278070, 1278072, 1278074)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: reserved reference namespace collision';
    END IF;
    IF EXISTS (SELECT 1 FROM `creature_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `disenchant_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `fishing_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `gameobject_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `mail_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `milling_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `pickpocketing_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `prospecting_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `skinning_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `spell_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506))
        OR EXISTS (SELECT 1 FROM `player_loot_template`
            WHERE ABS(`Reference`) IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506)) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: references used by another loot store';
    END IF;
    IF EXISTS (SELECT 1 FROM `conditions`
        WHERE (`SourceTypeOrReferenceId` = 10
            AND `SourceGroup` IN (9003501,9003502,9003503,9003504,9003505,9003506))
            OR (`SourceTypeOrReferenceId` = 5 AND `SourceGroup` IN (1278070,1278072,1278074))) THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: existing loot conditions require review';
    END IF;
    DELETE FROM `reference_loot_template`
    WHERE `Entry` IN (9003501, 9003502, 9003503, 9003504, 9003505, 9003506);
    INSERT INTO `reference_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    SELECT `Pool`, `Item`, 0, 0, 0, 1, 1, 1, 1, 'MS Classic AQ20 cache family pool'
    FROM `tmp_ms_aq20_candidate`;
    DELETE FROM `item_loot_template` WHERE `Entry` IN (1278070, 1278072, 1278074);
    INSERT INTO `item_loot_template`
        (`Entry`, `Item`, `Reference`, `Chance`, `QuestRequired`, `LootMode`, `GroupId`,
            `MinCount`, `MaxCount`, `Comment`)
    VALUES
    (1278070, 1, 9003504, 100, 0, 1, 1, 1, 1, 'MS AQ20: guaranteed Mythic BWL'),
    (1278070, 2, 9003501, 100, 0, 1, 2, 1, 1, 'MS AQ20: guaranteed Normal AQ20'),
    (1278070, 3, 9003505, 10, 0, 1, 3, 1, 1, 'MS AQ20: optional Mythic 11-20 Dungeon'),
    (1278072, 1, 9003501, 100, 0, 1, 1, 1, 1, 'MS AQ20: guaranteed Normal AQ20'),
    (1278072, 2, 9003501, 50, 0, 1, 2, 1, 1, 'MS AQ20: optional second Normal AQ20'),
    (1278072, 3, 9003502, 10, 0, 1, 3, 1, 1, 'MS AQ20: optional Heroic AQ20'),
    (1278072, 4, 9003505, 10, 0, 1, 4, 1, 1, 'MS AQ20: optional Mythic 11-20 Dungeon'),
    (1278074, 1, 9003502, 100, 0, 1, 1, 1, 1, 'MS AQ20: guaranteed Heroic AQ20'),
    (1278074, 2, 9003503, 10, 0, 1, 2, 1, 1, 'MS AQ20: optional Mythic AQ20'),
    (1278074, 3, 9003506, 10, 0, 1, 3, 1, 1, 'MS AQ20: optional Mythic 21-30 Dungeon');
    IF (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278070) <> 3
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278072) <> 4
        OR (SELECT COUNT(*) FROM `item_loot_template` WHERE `Entry` = 1278074) <> 3
        OR (SELECT COUNT(*) FROM `reference_loot_template`
            WHERE `Entry` IN (9003501,9003502,9003503,9003504,9003505,9003506)) <> 12714 THEN
        SIGNAL SQLSTATE '45000' SET MESSAGE_TEXT = 'AQ20 caches: post-write row count mismatch';
    END IF;
    COMMIT;
END$$
DELIMITER ;
CALL `ms_aq20_cache_restore_20261007`();
DROP PROCEDURE `ms_aq20_cache_restore_20261007`;

SELECT `Entry`, `Reference`, `Chance`, `GroupId`, `MinCount`, `MaxCount`
FROM `item_loot_template` WHERE `Entry` IN (1278070,1278072,1278074) ORDER BY `Entry`, `Item`;
SELECT `Entry`, COUNT(*) AS `Candidates`
FROM `reference_loot_template`
    WHERE `Entry` IN (9003501,9003502,9003503,9003504,9003505,9003506)
GROUP BY `Entry`;
DROP TEMPORARY TABLE `tmp_ms_aq20_candidate`;
